def _num(x, default=0):
    try:
        f = float(x)
        return int(f) if f == int(f) else f
    except (TypeError, ValueError):
        return default


def _int(x):
    return int(_num(x))


def _truthy(x):
    if x is None:
        return False
    if isinstance(x, str):
        return x.strip().lower() not in ("", "false", "0", "off", "no", "null",
                                          "unknown", "unavailable", "none")
    return bool(x)


def _both_numeric(a, b):
    try:
