        return state.getattr(str(entity_id)).get("friendly_name", str(entity_id))
    except Exception:
        return str(entity_id)


def _event_description():
    """$currentEventDescription — webCoRE's human sentence about the event that
    woke the piston. Rebuilt from the trigger kwargs available here."""
    try:
        name = _fname(var_name) if var_name else "something"
        return f"{name} is {value}"
    except Exception:
        return ""


def _sys_alarm():
    """$alarmSystemStatus as a webCoRE-shaped word."""
    try:
        raw = str(state.get(_ALARM_ENTITY)) if _ALARM_ENTITY else None
    except Exception:
        raw = None
    return {"armed_away": "armedAway", "armed_home": "armedHome",
            "armed_night": "armedNight", "disarmed": "disarmed",
            "triggered": "alarmActive"}.get(raw, raw or "")


def _now_min():
    n = datetime.datetime.now()
    return n.hour * 60 + n.minute


def _sun_min(event):
    """Minutes-since-midnight of today's sunrise/sunset, from HA's sun entity."""
    attr = "next_rising" if str(event).lower().startswith("sunrise") else "next_setting"
    try:
        v = state.getattr("sun.sun").get(attr)
        dt = datetime.datetime.fromisoformat(str(v)).astimezone()
        return dt.hour * 60 + dt.minute
    except Exception:
        return 360 if attr == "next_rising" else 1080


def _as_min(v):
    """Coerce a time-ish value to minutes since midnight (epoch ms, ms since
    midnight, or an already-minutes number)."""
    n = _num(v, None)
    if n is None:
        return 0
    if n > 86400000:
        d = _to_dt(n)
        return d.hour * 60 + d.minute
    if n > 1440:
        return int(n // 60000)
    return int(n)


def _pv_save():
    """Persist piston-local variables onto the piston's state entity so they
    survive HA restarts and recompiles (webCoRE parity)."""
    try:
        state.setattr(_STATE_ENTITY + ".vars", dict(pv))
    except Exception as exc:
        log.warning(f"could not persist variables: {exc}")


def _pv_set(name, value):
    pv[name] = value
    _pv_save()
    return value


def _s(name):
    """Forgiving state read -> string or None (research §9 locked rule)."""
    try:
        return str(state.get(name))
    except Exception:
        return None


def _f(name):
    """Forgiving numeric state read -> float or None (research §9 locked rule)."""
    try:
        return float(state.get(name))
    except Exception:
        return None


def _sa(name, field, mult=None, div=None):
    """Forgiving read of a reading that lives INSIDE an entity -> string/None.

    HA reports some readings as their own entity (state IS the value) and
    others as a field on another entity: a thermostat's current temperature
    is inside climate.x, whose state is "heat". Same rule the YAML band
    applies with state_attr(); the compiler decides which via one shared
    Resolver.read_spec(), and each band only spells it (Jeremy, 2026-07-29).

    state.getattr() is used rather than pyscript's dotted state.get()
    attribute form so this doesn't depend on that syntax behaving as
    expected. mult/div apply the vocab's unit conversion (HA brightness is
    0-255 where webCoRE's level is 0-100)."""
    try:
        v = (state.getattr(name) or {}).get(field)
    except Exception:
        return None
    if v is None:
        return None
    if mult is None:
        return str(v)
    try:
        return str(int(round(float(v) * mult / (div or 1))))
    except Exception:
        return None


def _fa(name, field, mult=None, div=None):
    """Numeric form of _sa -> float or None."""
    try:
        v = (state.getattr(name) or {}).get(field)
    except Exception:
        return None
    if v is None:
        return None
    try:
        v = float(v)
    except Exception:
        return None
    return v if mult is None else round(v * mult / (div or 1))


def _time_between(a, b):
    """$time between two times, minutes since midnight, wraps past midnight."""
    now = datetime.datetime.now()
    m = now.hour * 60 + now.minute
    return (a <= m <= b) if a <= b else (m >= a or m <= b)


