# -- math --
def _fn_sin(x):
    return math.sin(_num(x))


def _fn_cos(x):
    return math.cos(_num(x))


def _fn_tan(x):
    return math.tan(_num(x))


def _fn_asin(x):
    try:
        return math.asin(_num(x))
    except ValueError:
        return None


def _fn_atan2(y, x):
